using WorldWeaver;
using WorldWeaver.Editor.Assistant;

/// <summary>
/// Sends factual source-review feedback to the original private real-model chat.
/// A new full source is generated by the model, retained for review and exported outside Assets.
/// The original failed draft/history plan is preserved; this runner never applies a pending plan.
/// </summary>
public static class MechanicRepairAcceptanceRunner
{
    const string OriginalCodeSha="6536bcb057834901e80e8fd774081eafd102341a7aabee5b8d6133113f48d9a5";
    const string OriginalReceiptSha="0d1de3e0559baf1d860a999eb5331d8a99cacdc45ba191e229f65b40cfc364cf";
    const string ReviewReceiptSha="5b12445048459ceadb3012b79155c35315cb5eb6f755e9bdc7dde27db25beeed";
    static bool running;
    public static async void Run()
    {
        if(!Application.isBatchMode||Environment.GetEnvironmentVariable("WW_MECHANIC_REPAIR_ACCEPTANCE")!="1")
            throw new InvalidOperationException("Explicit WW_MECHANIC_REPAIR_ACCEPTANCE=1 and disposable batch mode are required.");
        if(running)throw new InvalidOperationException("A mechanic review-feedback run is already active.");running=true;
        string output=null,project=Directory.GetParent(Application.dataPath).FullName,package=null,input=null,history=null;
        bool outputApproved=false,passed=false,oldBackground=Application.runInBackground;
        ChatController controller=null;OllamaModelDiscovery discovery=null;Action changed=null;
        Dictionary<string,string> packageBefore=null,scriptsBefore=null;JArray previousMessages=null;JObject original=null;
        var checks=new JObject();var failures=new JArray();var captured=new JObject();var drafts=new JArray();var watch=Stopwatch.StartNew();
        var report=new JObject { ["schemaVersion"]=1,["kind"]="actual-main-chat-review-feedback-mechanic-draft",["runner"]=typeof(MechanicRepairAcceptanceRunner).FullName,
            ["startedUtc"]=DateTime.UtcNow.ToString("O"),["unityVersion"]=Application.unityVersion,["success"]=false,["passed"]=false,
            ["providerMode"]="real-local-Ollama-inference",["providerFactoryInjected"]=false,["paidApiUsed"]=false,["externalApiRequested"]=false,
            ["scriptReviewGranted"]=false,["pendingPlansAppliedByRunner"]=0,["manualSemanticReviewRequired"]=true,
            ["capturedReviewOnlyPlans"]=captured,["drafts"]=drafts,["checks"]=checks,["failureReasons"]=failures,
            ["limitations"]=new JArray("A model response to one factual review of one failed draft, not a correctness or reliability estimate.",
                "Success means a new retained full-source candidate and preserved provenance. The corrected behavior is not accepted until independent review, real compilation and real F-edge/color measurement.",
                "No original or corrected source is imported, patched, approved or attached by this runner. Original failed source and its pending history message remain unchanged.") };
        try
        {
            if(Path.GetFullPath(Required("WW_MECHANIC_REPAIR_DISPOSABLE_PROJECT"))!=Path.GetFullPath(project))throw new InvalidOperationException("The exact disposable project must be explicitly identified.");
            input=Path.GetFullPath(Required("WW_MECHANIC_REPAIR_INPUT"));output=Path.GetFullPath(Required("WW_MECHANIC_REPAIR_OUTPUT"));
            package=ResolvePackage();
            if(Within(output,Application.dataPath)||Within(output,Path.Combine(project,"Packages"))||Within(output,package)||output==input||File.Exists(output))
                throw new InvalidOperationException("Use a NEW output outside Assets, Packages and the immutable package, distinct from the original receipt.");
            outputApproved=true;
            if(!File.Exists(input)||Hash(File.ReadAllBytes(input))!=OriginalReceiptSha)throw new InvalidOperationException("The original R6 receipt does not match its fixed SHA256.");
            original=JObject.Parse(File.ReadAllText(input),new JsonLoadSettings {DuplicatePropertyNameHandling=DuplicatePropertyNameHandling.Error});
            string reviewPath=Environment.GetEnvironmentVariable("WW_MECHANIC_REPAIR_REVIEW")??Path.Combine(Path.GetDirectoryName(input),"mechanic-semantic-review-1.3-r6.json");
            reviewPath=Path.GetFullPath(reviewPath);
            if(!File.Exists(reviewPath)||Hash(File.ReadAllBytes(reviewPath))!=ReviewReceiptSha)throw new InvalidOperationException("The independent FAIL review receipt does not match its fixed SHA256.");
            var review=JObject.Parse(File.ReadAllText(reviewPath));
            if((string)review["reviewedSourceSha256"]!=OriginalCodeSha||(bool?)review["accepted"]!=false)throw new InvalidOperationException("Review is not the bound rejected source.");
            var previousDraft=((JArray)original["drafts"]).OfType<JObject>().Single(d=>(string)d["sourceSha256"]==OriginalCodeSha);
            string previousPath=Path.GetFullPath((string)previousDraft["sourcePath"]);byte[] previousBytes=File.ReadAllBytes(previousPath);
            if(previousBytes.Length!=852||Hash(previousBytes)!=OriginalCodeSha)throw new InvalidOperationException("The exact852-byte rejected source changed.");
            string previousCode=new UTF8Encoding(false,true).GetString(previousBytes),sessionId=(string)original["sessionId"];
            if(Hash(Encoding.UTF8.GetBytes(previousCode))!=OriginalCodeSha||!ChatHistoryStore.ValidId(sessionId))throw new InvalidOperationException("Invalid source encoding or original session identity.");
            history=Path.GetFullPath((string)original["historyFolder"]);
            string historyBase=Path.Combine(project,"UserSettings","WorldWeaverChatAcceptance");
