            var old=stored.Messages.Where(m=>m.PendingPlan?.actions?.Count==1&&m.PendingPlan.actions[0].tool=="draft_script"&&Hash(Encoding.UTF8.GetBytes((string)m.PendingPlan.actions[0].args["code"]))==OriginalCodeSha).ToArray();
            if(old.Length!=1||!JToken.DeepEquals(original["capturedReviewOnlyPlans"]?[old[0].Id],JObject.FromObject(old[0].PendingPlan)))
                throw new InvalidOperationException("The old pending plan no longer matches the exact captured review-only plan.");
            ScriptDrafts.Validate(old[0].PendingPlan.actions[0]);
            report["originalReceiptPath"]=input;report["originalReceiptSha256"]=OriginalReceiptSha;report["reviewReceiptPath"]=reviewPath;report["reviewReceiptSha256"]=ReviewReceiptSha;
            report["rejectedSourcePath"]=previousPath;report["rejectedSourceSha256"]=OriginalCodeSha;report["rejectedSourceBytes"]=852;
            report["sessionId"]=sessionId;report["historyFolder"]=history;report["originalMessageId"]=old[0].Id;
            checks["originalReceiptReviewSourceAndPendingPlanHashBound"]=true;
